#!/usr/bin/env python3
"""Build a self-contained, filterable view of the published benchmark rows."""
import json
from pathlib import Path

root = Path('docs/accuracy')
rows = [json.loads(line) for line in (root / 'results.jsonl').read_text().splitlines()]
compact = [{k: r[k] for k in ('case', 'language', 'model', 'mode', 'version', 'seconds', 'reference_words', 'hypothesis_words', 'accuracy', 'errors', 'wall_s', 'cpu_user_s', 'cpu_sys_s', 'rss_kib', 'threads')} | {'text': r['result']['text'][:600] + ('…' if len(r['result']['text']) > 600 else '')} for r in rows]
page = r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dictado · mediciones</title><style>
:root{font-family:var(--font-sans,system-ui);color:var(--foreground,#ddd);color-scheme:light dark}body{margin:0;background:transparent}p{line-height:1.45;margin:0 0 12px}small,.note{color:var(--muted-foreground,#888);font-size:12px}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}label{display:flex;flex-direction:column;gap:4px;font-size:12px}select,button{font:inherit;padding:7px 9px;border:1px solid var(--border,#666);border-radius:var(--radius,6px);background:var(--secondary,#222);color:var(--foreground,#ddd)}button{cursor:pointer}button[aria-pressed=true]{background:var(--accent-surface,#293a4a)}.scroll{overflow:auto;max-height:800px;border-bottom:1px solid var(--border,#555)}table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}th,td{padding:9px 8px;border-bottom:1px solid var(--border,#444);text-align:right}th:first-child,td:first-child{text-align:left}th{position:sticky;top:0;background:var(--background,#161616);z-index:1}td{font-family:var(--font-mono,monospace)}.up{color:var(--success,#6bba80)}.down{color:var(--destructive,#ef8888)}details{white-space:normal;min-width:45px;font-family:var(--font-sans,system-ui)}details p{max-width:580px;white-space:normal;margin:8px 0}summary{cursor:pointer;text-align:left}#status{margin-bottom:8px}.foot{margin-top:12px}a{color:var(--accent,#8bb9ff)}
</style><body>
<p><strong>Dictado: precisión y recursos</strong><br><small id="scope"></small></p>
<p class="note">Porcentajes = 100 × (1 − WER), contra el mismo prefijo estimado del artículo para cada variante. Hay recortes anidados de una misma voz por idioma. Los tiempos se midieron en un escritorio con contención de CPU/memoria y swap; son observaciones individuales.</p>
<div class="controls"><label>Idioma<select id="language"><option value="all">Todos</option><option value="es">Español</option><option value="en">Inglés</option><option value="pt">Portugués</option><option value="fr">Francés</option><option value="de">Alemán</option><option value="it">Italiano</option></select></label><label>Modelo q8_0<select id="model"><option value="small">small</option><option value="base">base</option><option value="all" selected>Ambos</option></select></label><label>Idioma del motor<select id="mode"><option value="auto">Automático</option><option value="fixed">Fijo</option><option value="all" selected>Ambos</option></select></label></div>
<div class="controls"><button id="accuracy" aria-pressed="true">Precisión</button><button id="resources" aria-pressed="false">Recursos</button><button id="regressions">Solo retrocesos</button><button id="export">Exportar CSV de métricas</button></div>
<p class="note" id="status"></p><div class="scroll"><table><thead id="head"></thead><tbody id="body"></tbody></table></div>
<p class="note foot">M2 Pro · 12 núcleos · CPU · 8 hilos. base: 81.768.585 bytes; small: 264.464.607 bytes. Binarios medidos: 1.578.520 bytes cada uno. <a href="https://github.com/avillagran/omarchy-dictation/blob/main/docs/ACCURACY.md" target="_blank" rel="noopener">Método, corpus, límites y reproducción</a>. <a href="https://github.com/avillagran/omarchy-dictation/blob/main/docs/accuracy/results.jsonl" target="_blank" rel="noopener">Transcripciones completas y datos originales</a>.</p>
<script>
const rows=__DATA__;
const groups=new Map();for(const r of rows){const key=[r.case,r.model,r.mode].join('/');if(!groups.has(key))groups.set(key,{});groups.get(key)[r.version]=r;}
const pairs=[...groups.values()].filter(p=>p.before&&p.after);let view='accuracy',regressions=false;
const $=id=>document.getElementById(id),fmt=(n,d=1)=>Number(n).toFixed(d);
$('scope').textContent=`${new Set(rows.map(r=>r.case)).size} casos · ${rows.length} ejecuciones · 6 idiomas · antes → después`;
function cell(row,text,cls){const td=document.createElement('td');td.textContent=text;if(cls)td.className=cls;row.append(td);return td;}
function draw(){const chosen=pairs.filter(p=>($('language').value==='all'||p.after.language===$('language').value)&&($('model').value==='all'||p.after.model===$('model').value)&&($('mode').value==='all'||p.after.mode===$('mode').value)&&(!regressions||p.after.accuracy<p.before.accuracy));$('head').replaceChildren();$('body').replaceChildren();const tr=document.createElement('tr');const headings=view==='accuracy'?['Caso · modelo · idioma','s','N ref.','Antes %','Después %','Δ pp','Extracto']:['Caso · modelo · idioma','Pared s','CPU s','RSS MiB','Hilos'];for(const h of headings){const th=document.createElement('th');th.textContent=h;tr.append(th);}$('head').append(tr);
for(const p of chosen){const b=p.before,n=p.after,r=document.createElement('tr');cell(r,`${n.case} · ${n.model} · ${n.mode==='auto'?'auto':'fijo'}`);if(view==='accuracy'){cell(r,fmt(n.seconds));cell(r,n.reference_words);cell(r,fmt(b.accuracy));cell(r,fmt(n.accuracy));const delta=n.accuracy-b.accuracy;cell(r,(delta>0?'+':'')+fmt(delta),delta>0?'up':delta<0?'down':'');const td=cell(r,'');const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Ver';details.append(summary);for(const [title,value] of [['Antes',b.text],['Después',n.text]]){const para=document.createElement('p'),strong=document.createElement('strong');strong.textContent=title+': ';para.append(strong,document.createTextNode(value||'∅'));details.append(para);}td.append(details);}else{cell(r,`${fmt(b.wall_s,2)} → ${fmt(n.wall_s,2)}`);cell(r,`${fmt(b.cpu_user_s+b.cpu_sys_s,2)} → ${fmt(n.cpu_user_s+n.cpu_sys_s,2)}`);cell(r,`${fmt(b.rss_kib/1024)} → ${fmt(n.rss_kib/1024)}`);cell(r,n.threads);}$('body').append(r);}
$('status').textContent=`${chosen.length} comparaciones. N = palabras de referencia, no conteo manual de palabras habladas.`;
}
for(const id of ['language','model','mode'])$(id).addEventListener('change',draw);
for(const id of ['accuracy','resources'])$(id).onclick=()=>{view=id;for(const tab of ['accuracy','resources'])$(tab).setAttribute('aria-pressed',String(tab===id));draw();};
$('regressions').onclick=()=>{regressions=!regressions;$('regressions').setAttribute('aria-pressed',String(regressions));draw();};
$('export').onclick=()=>{const fields=Object.keys(rows[0]).filter(k=>k!=='text');const csv=[fields,...rows.map(r=>fields.map(k=>r[k]))].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='dictation-benchmark.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
draw();console.assert(rows.length===200,'Expected 200 measurements');console.assert(pairs.length===100,'Expected 100 before/after pairs');$('language').value='de';draw();console.assert($('body').children.length===16,'German filter');$('language').value='all';$('model').value='small';$('mode').value='auto';draw();console.assert($('body').children.length===25,'Small automatic filter');$('resources').click();console.assert($('head').firstChild.children.length===5,'Resource columns');$('accuracy').click();$('model').value='all';$('mode').value='all';draw();console.log('BENCHMARK_TABLE',JSON.stringify({runs:rows.length,cases:new Set(rows.map(r=>r.case)).size,pairs:pairs.length}));
</script></body></html>'''
(root / 'report.html').write_text(page.replace('__DATA__', json.dumps(compact, ensure_ascii=False).replace('<', '\\u003c')))
print(root / 'report.html')
